package com.example.backend

import android.util.Log
import com.example.BuildConfig

/**
 * Supabase configuration manager for FinSense.
 * Supports production secret injection via BuildConfig (.env / AI Studio Secrets panel),
 * runtime overrides for evaluator testing, and zero-crash standalone fallback when secrets are kept blank.
 */
object SupabaseConfig {
    private const val TAG = "SupabaseConfig"

    // Default base URL read safely from BuildConfig generated by Secrets Gradle Plugin
    val defaultUrl: String = try {
        BuildConfig.SUPABASE_URL
    } catch (_: Throwable) {
        ""
    }

    val defaultAnonKey: String = try {
        BuildConfig.SUPABASE_ANON_KEY
    } catch (_: Throwable) {
        ""
    }

    // Runtime overrides for hackathon testing or evaluators
    private var runtimeUrl: String? = null
    private var runtimeAnonKey: String? = null

    var currentUrl: String
        get() = runtimeUrl ?: defaultUrl.trim()
        set(value) {
            runtimeUrl = value.trim()
        }

    var currentAnonKey: String
        get() = runtimeAnonKey ?: defaultAnonKey.trim()
        set(value) {
            runtimeAnonKey = value.trim()
        }

    val isConfigured: Boolean
        get() {
            val url = currentUrl
            val key = currentAnonKey
            return url.isNotBlank() &&
                    !url.contains("YOUR_") &&
                    !url.contains("placeholder", ignoreCase = true) &&
                    key.isNotBlank() &&
                    !key.contains("YOUR_") &&
                    !key.contains("placeholder", ignoreCase = true)
        }

    fun getNormalizedBaseUrl(): String {
        var url = currentUrl
        if (url.isBlank()) return ""
        if (!url.startsWith("http://") && !url.startsWith("https://")) {
            url = "https://$url"
        }
        if (!url.endsWith("/")) {
            url = "$url/"
        }
        return url
    }

    fun resetToDefaults() {
        runtimeUrl = null
        runtimeAnonKey = null
        Log.d(TAG, "Reset Supabase config to BuildConfig values (Configured: $isConfigured)")
    }
}

enum class BackendConnectionStatus {
    STANDALONE_SUBMISSION, // Secrets blank as per code submission guidelines; local data layer active
    CONNECTING,            // Validating credentials against Supabase endpoint
    CONNECTED_LIVE,        // Verified active connection to Supabase PostgREST backend
    CONNECTION_ERROR       // Endpoint returned error or timeout; seamlessly fell back to local cache
}
